package com.gymmind.membership.infrastructure.persistence; import com.gymmind.membership.domain.model.MembershipPackage; import com.gymmind.membership.domain.repository.MembershipPackageRepository; import org.springframework.stereotype.Repository; import java.util.Optional; @Repository class JpaMembershipPackageRepository implements MembershipPackageRepository{private final SpringDataMembershipPackageRepository d;JpaMembershipPackageRepository(SpringDataMembershipPackageRepository d){this.d=d;}public MembershipPackage save(MembershipPackage p){return d.save(p);}public Optional<MembershipPackage> findByTenantIdAndId(Long t,Long id){return d.findByTenantIdAndId(t,id);}}
